import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Crimson/Seastor OSD Weekly 2020-06-10","description":"","frontmatter":{"title":"Ceph Crimson/Seastor OSD Weekly 2020-06-10","date":"2020-06-10T00:00:00.000Z","updated":"2020-06-10T00:00:00.000Z","tags":["Ceph","Distributed Storage","Performance Optimization","Memory Allocator","System Failures","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_Seastor_OSD_Weekly_2020-06-10.md","filePath":"posts/2020/Ceph_Crimson_Seastor_OSD_Weekly_2020-06-10.md","lastUpdated":1780459816000}'),s={name:"posts/2020/Ceph_Crimson_Seastor_OSD_Weekly_2020-06-10.md"};function l(i,e,n,h,d,_){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>异步版本开发</strong>：计划开发异步版本，重点关注处理repellents of the leaf notice。</li><li><strong>性能测试</strong>：进行了两个分支的性能测试，包括graceful shutdown PR，发现其对性能有3.5%的惩罚。从istil到Lipsy的内存分配器转换对性能有50%的影响。</li><li><strong>内存分配器问题</strong>：讨论了sister&#39;s memory allocator和alien stars的问题，发现多线程环境下的内存分配存在重要误解和实际问题。</li><li><strong>系统崩溃分析</strong>：分析了系统崩溃的原因，与sister memory allocator的内存分配问题有关，特别是在处理大量线程时。</li><li><strong>后续行动计划</strong>：计划进一步调查和优化sister memory allocator，特别是多线程环境下的表现，并调整系统的内存分配策略。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>异步版本开发</strong>：讨论异步版本的开发计划和进展。</li><li><strong>性能测试结果</strong>：分享性能测试结果，特别是graceful shutdown PR和内存分配器转换的影响。</li><li><strong>内存分配器问题</strong>：深入讨论sister&#39;s memory allocator和alien stars的问题，包括其在多线程环境下的表现和存在的问题。</li><li><strong>系统崩溃原因</strong>：分析系统崩溃的原因，特别是在处理大量线程时的内存分配问题。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>异步版本开发</strong>：决定在下一周尝试开发异步版本，特别是在处理repellents of the leaf notice方面。</li><li><strong>性能测试</strong>：确认性能测试的结果，并决定进一步调查和优化内存分配器。</li><li><strong>内存分配器问题</strong>：决定进一步调查和优化sister&#39;s memory allocator，特别是在多线程环境下的表现。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>异步版本开发</strong>：继续开发异步版本，并关注其在实际应用中的表现。</li><li><strong>性能测试</strong>：继续进行性能测试，并根据测试结果调整和优化内存分配策略。</li><li><strong>内存分配器问题</strong>：进一步调查和优化sister&#39;s memory allocator，特别是在多线程环境下的表现。</li><li><strong>系统崩溃原因</strong>：继续分析系统崩溃的原因，并寻找解决方案。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议主要讨论了异步版本的开发、性能测试结果、内存分配器问题以及系统崩溃的原因。决定继续开发异步版本，并进一步调查和优化内存分配器。同时，需要继续分析系统崩溃的原因，并寻找解决方案。</p>',12)])])}const m=t(s,[["render",l]]);export{g as __pageData,m as default};
